D("D001","mathbbT","measured periodic domain","mathbbT=R/(2*pi*Z), with normalized measure dx/(2*pi).");
D("D002","Fourier","Fourier coefficient transform","For a periodic integrable f, hat f(k)=(2*pi)^(-1) integral_0^(2*pi) f(x) exp(-i*k*x) dx. The transform extends by completion to Sobolev spaces and by distributional duality. Reality means hat f(-k)=conjugate(hat f(k)); mean zero means hat f(0)=0.",["D001"],[b("f","periodic integrable function"),b("k","integer"),b("x","spatial integration variable")],["mathbbT"]);
D("D003","H","family of Fourier Sobolev spaces and norms","For real s, <k>=(1+k^2)^(1/2), ||f||_(H^s)^2=sum_(k in Z) <k>^(2*s)|hat f(k)|^2. H^s is the completion of trigonometric polynomials, interpreted as distributions for negative s; L2=H^0 with the normalized spatial norm. On mean-zero functions ||f||_(dot H^s)^2=sum_(k!=0)|k|^(2*s)|hat f(k)|^2. Time suprema use continuous representatives and derivative norms essential suprema. For sequences x, ||x||_(ell2)^2=sum_k |x(k)|^2; ell1 uses sum_k |x(k)|. Frequency projections P_{<=A}, P_{>A} retain respectively |k|<=A and |k|>A.",["D001","D002"],[b("s","real number"),b("f","periodic distribution"),b("k","integer"),b("x","complex sequence"),b("A","nonnegative real threshold")],["mathbbT","Fourier"]);
D("D004","S","one-parameter Fourier multiplier group","S_t=exp(-t*partial_x^3), hat(S_t f)(k)=exp(i*t*k^3)*hat f(k), for every real t.",["D002","D003"],[b("t","real number"),b("f","periodic distribution"),b("k","integer")],["Fourier","H"]);
D("D005","P0","spatial mean projection","P0 f=hat f(0), identified with the constant function.",["D002"],[b("f","periodic distribution")],["Fourier"]);
D("D006","P","mean-zero projection","P=I-P0.",["D005"],[],["P0"]);
D("D007","Dinv","inverse spatial derivative Fourier multiplier","Dinv=D^(-1)=partial_x^(-1): its multiplier is (i*k)^(-1) at k!=0 and zero at k=0. D^(-2)=Dinv composed with Dinv. Spatial derivatives use multiplier i*k.",["D002","D003"],[b("k","integer")],["Fourier","H"]);
const target=load("target");
D("D008","F_tau","family of quadratic spatial maps","For tau>0 and periodic f in L2, F_tau(f)=(1/6)*P[(S_tau Dinv f)^2]-(1/6)*S_tau P[(Dinv f)^2].",["D004","D006","D007"],[b("tau","positive real number"),b("f","periodic L2 function")],["P","S","Dinv"]);
D("D009","H_tau","family of cubic spatial maps","For tau>0 and periodic f in L2, H_tau(f)=(1/3)*P[(S_tau Dinv f)*Dinv F_tau(f)]+(tau/9)*(S_tau Dinv f)*P0(f^2)-(1/54)*[S_(tau-s) Dinv[(S_s Dinv f)^3]]_(s=0)^(s=tau)-(1/(27*tau))*[S_(tau-s) D^(-2)[(S_(s-tau) D^(-2) F_tau(f))*(S_s Dinv f)]]_(s=0)^(s=tau). Every product is spatial and [G(s)]_0^tau=G(tau)-G(0).",["D004","D005","D006","D007","D008"],[b("tau","positive real number"),b("f","periodic L2 function"),b("s","endpoint evaluation variable")],["S","P0","P","Dinv","F_tau"]);
D("D010","Psi","unfiltered time-step map and its iterates","Psi_tau(f)=S_tau f+F_tau(f)+H_tau(f). For positive integer L set tau=T/L and t_n=n*tau. Define u^0=u0 and u^(n+1)=Psi_tau(u^n) for 0<=n<L. There is no spatial cutoff in this recurrence.",["D004","D008","D009"],[b("tau","positive real number"),b("f","periodic L2 function"),b("L","positive integer"),b("n","integer index"),b("u0","periodic L2 datum")],["T","S","F_tau","H_tau"]);
D("D011","eta","average phase covariance","For tau>0, M_tau g=tau^(-1) integral_0^tau g(s)ds and eta_tau(alpha,beta)=M_tau(exp(-i*s*(alpha+beta)))-M_tau(exp(-i*s*alpha))*M_tau(exp(-i*s*beta)).",[],[b("tau","positive real number"),b("alpha","real phase"),b("beta","real phase"),b("g","continuous function on [0,tau]"),b("s","time integration variable")],[]);
D("D012","R2","averaged cubic Fourier remainder family","For tau>0, t_n=n*tau and k!=0, hat(R2_(n,tau)(f1,f2,f3))(k)= -tau/(18*i*k) sum_(a+b+c=k,a+b!=0) exp(-i*t_n*Phi)*eta_tau(alpha,beta)*hat f1(a)*hat f2(b)*hat f3(c), with p=a+b, alpha=3*a*b*p, beta=3*k*c*p, Phi=alpha+beta=k^3-a^3-b^3-c^3. Output at k=0 is zero. Initially this formula is on Fourier polynomials; bounded extension is proved below. Terms with a zero input frequency vanish since one phase is zero.",["D002","D011"],[b("tau","positive real number"),b("n","nonnegative integer"),b("f1","Fourier polynomial"),b("f2","Fourier polynomial"),b("f3","Fourier polynomial"),b("k","integer output frequency"),b("a","integer summation frequency"),b("b","integer summation frequency"),b("c","integer summation frequency"),b("p","integer pair sum"),b("alpha","real phase"),b("beta","real phase"),b("Phi","real total phase")],["Fourier","eta"]);
D("D013","B","time-dependent bilinear differential operator","B_t(f,g)=S_(-t) partial_x[(S_t f)(S_t g)].",["D004","D007"],[b("t","real number"),b("f","smooth periodic function"),b("g","smooth periodic function")],["S","Dinv"]);
D("D014","J","time-dependent bilinear normal-form operator","J_t(f,g)=S_(-t) P[(S_t Dinv f)(S_t Dinv g)].",["D004","D006","D007"],[b("t","real number"),b("f","periodic L2 function"),b("g","periodic L2 function")],["S","P","Dinv"]);
D("D015","Cint","time-integrated trilinear operator","For I=[a,b] with 0<=a<=b, Cint_I(f,g,h)=integral_I S_(-t) P{P[(S_t f(t))(S_t g(t))]*(S_t Dinv h(t))}dt; time-independent inputs are read as constant paths.",["D004","D006","D007"],[b("I","closed nonnegative time interval"),b("a","left endpoint"),b("b","right endpoint"),b("t","time integration variable"),b("f","smooth periodic time path"),b("g","smooth periodic time path"),b("h","smooth periodic time path")],["S","P","Dinv"]);
