D("D017","a_gamma","product and stage exponent","For 0<gamma<=1, a_gamma=1/2-gamma if gamma<1/2; a_gamma=1/8 if gamma=1/2; and a_gamma=0 if gamma>1/2.",[],[],["gamma"],["H002"]);
D("D018","Stage","quadratic twisted stage","For tau>0, nonnegative integer n, t_n=n*tau and t in [t_n,t_n+tau], Stage_(n,tau)(t;f)= (1/2) integral_(t_n)^t B_s(f,f)ds, initially for a time-independent smooth mean-zero f; the endpoint normal form below gives its L2 extension.",["D013"],[b("tau","positive real number"),b("n","nonnegative integer"),b("t","stage time"),b("f","smooth mean-zero periodic function"),b("s","integration variable")],["B"]);
D("D019","Interp","step interpolation and residual construction","For smooth mean-zero step data f at t_n=n*tau, write F_n(t)=Stage_(n,tau)(t;f), z_n=f+F_n, C_n(t)=integral_(t_n)^t B_s(f,F_n(s))ds, Q_n(t)=(1/2)integral_(t_n)^t B_s(F_n(s),F_n(s))ds, W_n=Q_n(t_n+tau)+R2_(n,tau)(f,f,f), V_n(t)=f+F_n(t)+C_n(t)+Q_n(t)-(t-t_n)*W_n/tau, Y_n=V_n-z_n, rho_n(t)=-integral_(t_n)^t B_s(Y_n,z_n)ds-(1/2)integral_(t_n)^t B_s(Y_n,Y_n)ds-(t-t_n)*W_n/tau. For f=S_(-t_n)u^n, concatenate V_n as V and the increments rho_n as Rres, with Rres(0)=0. Continuity of V at grid points is a proved property, not an assumption.",["D004","D010","D012","D013","D018"],[b("tau","positive real number"),b("n","nonnegative step index"),b("t","time in the step"),b("f","smooth mean-zero periodic function"),b("s","time integration variable")],["S","Psi","R2","B","Stage"]);
